using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;

namespace CommandBars.Designer.Client;

/// <summary>One built-in stock icon: its key, SVG markup (embedded into the
/// SvgImageList when chosen), and a pre-rendered PNG thumbnail (base64) so the
/// client gallery needs no SVG renderer.</summary>
internal sealed class StockIcon
{
    public StockIcon(string key, string svg, string pngBase64)
    {
        Key = key;
        Svg = svg;
        _pngBase64 = pngBase64;
    }

    public string Key { get; }
    public string Svg { get; }
    private readonly string _pngBase64;

    /// <summary>Decodes the thumbnail into an independent Bitmap (caller owns it).</summary>
    public Image CreateThumbnail()
    {
        byte[] bytes = Convert.FromBase64String(_pngBase64);
        using var ms = new MemoryStream(bytes);
        using var img = Image.FromStream(ms);
        return new Bitmap(img);
    }
}

